import React, { useEffect, useState } from "react";
import axios from "axios";
import "./dashboard.css";

function StudyTracker() {
  const userId = localStorage.getItem("user_id");

  const [courses, setCourses] = useState([]);
  const [logs, setLogs] = useState([]);
  const [today, setToday] = useState({ today_hours: 0, target_hours: 3 });
  const [weekly, setWeekly] = useState({ total_hours: 0, days_studied: 0, consistency: 0 });

  const [form, setForm] = useState({
    course_id: "",
    hours: "",
    topic: ""
  });

  const loadData = async () => {
    try {
      const c = await axios.get("http://127.0.0.1:8000/courses");
      const e = await axios.get(`http://127.0.0.1:8000/enrollments/${userId}`);

      const ids = e.data.map((i) => i.course_id);

      setCourses((c.data.courses || []).filter((x) => ids.includes(x.id)));

      const l = await axios.get(`http://127.0.0.1:8000/study-logs/${userId}`);
      setLogs(l.data.logs || []);

      const t = await axios.get(`http://127.0.0.1:8000/today-study/${userId}`);
      setToday(t.data);

      const w = await axios.get(`http://127.0.0.1:8000/weekly-summary/${userId}`);
      setWeekly(w.data);
    } catch (err) {
      console.log(err);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleSubmit = async (e) => {
    e.preventDefault();

    await axios.post("http://127.0.0.1:8000/study-log", {
      user_id: parseInt(userId),
      course_id: parseInt(form.course_id),
      study_date: new Date().toISOString().split("T")[0],
      hours: parseFloat(form.hours),
      topic: form.topic
    });

    setForm({ course_id: "", hours: "", topic: "" });
    loadData();
  };

  return (
    <div>
      <h2>📊 Study Tracker</h2>

      {/* TODAY CARD */}
      <div className="grid-3">
        <div className="stat-card">
          <h3>Today Study</h3>
          <p>{today.today_hours} hrs</p>
        </div>

        <div className="stat-card">
          <h3>Target</h3>
          <p>{today.target_hours} hrs</p>
        </div>

        <div className="stat-card">
          <h3>Remaining</h3>
          <p>{Math.max(today.target_hours - today.today_hours, 0)} hrs</p>
        </div>
      </div>

      {/* LOG FORM */}
      <div className="section-card">
        <h3>Log Study</h3>

        <form onSubmit={handleSubmit}>
          <select
            className="input"
            value={form.course_id}
            onChange={(e) => setForm({ ...form, course_id: e.target.value })}
          >
            <option value="">Select Course</option>
            {courses.map((c) => (
              <option key={c.id} value={c.id}>{c.title}</option>
            ))}
          </select>

          <input
            className="input"
            type="number"
            placeholder="Hours"
            value={form.hours}
            onChange={(e) => setForm({ ...form, hours: e.target.value })}
          />

          <input
            className="input"
            placeholder="Topic"
            value={form.topic}
            onChange={(e) => setForm({ ...form, topic: e.target.value })}
          />

          <button className="btn btn-primary">Save</button>
        </form>
      </div>

      {/* WEEKLY */}
      <div className="grid-3">
        <div className="stat-card">
          <h3>Weekly Hours</h3>
          <p>{weekly.total_hours}</p>
        </div>

        <div className="stat-card">
          <h3>Days Studied</h3>
          <p>{weekly.days_studied}/7</p>
        </div>

        <div className="stat-card">
          <h3>Consistency</h3>
          <p>{weekly.consistency}%</p>
        </div>
      </div>

      {/* LOG TABLE */}
      <div className="section-card">
        <h3>Recent Logs</h3>

        {logs.map((l) => (
          <div key={l.id} className="list-card">
            <b>{l.topic}</b>
            <div>{l.study_date}</div>
            <div>{l.hours} hrs</div>
          </div>
        ))}
      </div>
    </div>
  );
}

export default StudyTracker;
